-- Migration 015: Security Fixes
-- Fixes RLS and View warnings generated by Supabase Security Advisor.

-- 1. Enable RLS on admin_allowlist (prevents public access)
ALTER TABLE public.admin_allowlist ENABLE ROW LEVEL SECURITY;

-- 2. Make the jobs view use the invoker's security permissions (bypasses the SECURITY DEFINER warning)
ALTER VIEW public.jobs SET (security_invoker = true);
